/** Named viewing angles for a color. Each slot is one image URL or null.
 *  These are *per-color* angles used on the PDP gallery / AR try-on.
 *  ProductCard storefront imagery lives on `Product.cardImageUrl` instead.
 *
 *  front  — head-on, no model. Required for new SKUs.
 *  side   — 90° profile, full temple. Required for new SKUs.
 *  angle  — 3/4 view, the e-commerce default cover.
 *  folded — top-down, glasses folded. */
export type ColorViewKey = "front" | "side" | "angle" | "folded";
export type ColorViews = Record<ColorViewKey, string | null>;

export interface ColorImages {
  id: string;
  label: Record<string, string>;
  hex: string;
  /** Palette bucket (server-derived via nearestColorFamily). Null = legacy row. */
  colorFamily?: string | null;
  /** Ordered list of frame imagery for this color. images[0] is the hero. */
  images: string[];
  /** Named angle slots. Falls back to images[] when a view is null. */
  views?: ColorViews;
  /** Transparent-PNG overlay used by the try-on canvas. Null = fall back to images[0]. */
  tryonImageUrl?: string | null;
  /** GLB model path for the 3D try-on renderer. Null = 2D PNG overlay path. */
  tryonModelUrl?: string | null;
}

export type Category = "presbyopia" | "myopia";
export type Style = "minimal" | "business" | "character" | "classic";
export type Material = "acetate" | "metal" | "tr90" | "titanium";
export type Shape =
  | "round"
  | "square"
  | "aviator"
  | "cateye"
  | "oval"
  | "rectangle"
  | "butterfly"
  | "browline"
  | "geometric";
export type Gender = "unisex" | "women" | "men";

/** Multi-language map. Always has at least zh + en; other 8 langs optional. */
export type LangMap = Record<string, string>;

export interface Product {
  id: string;
  slug: string;
  /** Lang-keyed map. zh + en guaranteed; ja/ko/es/fr/de/it/pt/ar optional. */
  name: LangMap;
  /** One-line intro / tagline source. Lang-keyed; may be absent for legacy rows. */
  intro?: LangMap;
  categories: Category[];
  fashion: boolean; // 去老年化标签
  styles: Style[];
  material: Material;
  /** Surface treatment. Null = unspecified (legacy / pre-palette rows). */
  finish?: "matte" | "gloss" | "satin" | "brushed" | null;
  shape: Shape;
  /** Soft gender tags. A product can be tagged for multiple audiences. */
  genders: Gender[];
  priceUSD: number;
  originalPriceUSD?: number;
  weightG?: number;
  colors?: ColorImages[];
  rating: number;
  reviewCount: number;
  reviewQuality: number;
  reviewFit: number;
  reviewDesign: number;
  /** Lang-keyed bullet lists. {"zh": [...], "en": [...]}. */
  highlights: Record<string, string[]>;
  size: { lensWidth: number; bridge: number; temple: number }; // mm
  framePng: string; // for try-on overlay
  hero: string; // detail hero — reuse PNG
  /** Storefront ProductCard front face (clean 3/4 hero). Product-level — same across colors. */
  cardImageUrl?: string | null;
  /** Storefront ProductCard hover-flip back face (lifestyle / model-worn). Product-level. */
  cardHoverImageUrl?: string | null;
  isNew?: boolean;
  bestseller?: boolean;
  /** Lens primary categories the frame can be paired with at checkout. */
  supportsReader?: boolean;
  supportsSingleVision?: boolean;
  supportsProgressive?: boolean;
  supportsNonPrescription?: boolean;
}

